views['today.hero'] = function (st, r, c) {
const F = FP, L = F.L, $ = F.money, neg = st.count && st.net < 0, ex = st.ex >= .005 ? st.ex : 0;
let sp = '', ch = '', card;
if (st.count && (r === 7 || r === 30)) {
const ks = K.keptSeries(r), f = F.periodBounds(r)[0], d = r * 864e5;
sp = K.spark(ks, { k: 'today.spark' });
if (F.state().blocks.some((b) => { const t = Date.parse(b.start); return t >= f - d && t < f && F.isPaid(b); })) {
const x = Math.round(ks[r - 1] - K.keptBetween(f - d, f - 1));
ch = `<div class="bx-hc">${K.chip(x > 0 ? 'up' : x < 0 ? 'down' : '', x > 0 ? '+' + $(x, 0) : $(x, 0), x > 0 ? 'good' : '')}<span class="bx-sb">${K.nb(L('vs the {n} days before', { n: r }))}</span></div>`;
}
}
if (st.count) {
const sh = neg ? [] : K.shares([st.net, st.veh, ex]);
card = `<div class="bx-card bx-pay"><div class="bx-ch"><span>${K.nb(L('Pay and tips · {n} {blocks}', { n: st.count, blocks: F.plural(st.count, 'block') }))}</span><b class="bx-num">${$(st.gross)}</b></div>`
+ K.stack(neg ? [{ v: st.veh, c: 0 }, { v: ex, c: 1 }] : [{ v: st.net, c: 'green' }, { v: st.veh, c: 0 }, { v: ex, c: 1 }], { k: 'today.stack', label: L('Where your pay went'), marker: neg ? st.gross / (st.veh + ex) : 0 })
+ K.legend([{ c: 'green', label: L('You kept'), amt: $(st.net), strong: 1, neg, share: sh[0] }, { c: 0, label: K.nb(L('Car cost · {mi}', { mi: F.mi(st.miles) })), amt: '−' + $(st.veh), share: sh[1] }].concat(ex ? [{ c: 1, label: L('Other expenses'), amt: '−' + $(ex), share: sh[2] }] : [])) + '</div>';
} else card = `<div class="bx-card bx-sent">${c.blk ? L('Your money shows here after you save this block') : r === 'today' ? L('No blocks today yet. Your money shows up here after your first block.') : L('No blocks in this period yet.')}</div>` + (ex ? `<p class="hnote">${L('Bills and expenses in this period: {v}. They come off what you make once you drive.', { v: $(st.ex) })}</p>` : '');
return `<div class="bx-tile bx-hero"><div class="bx-hh"><span class="bx-k">${c.title}</span>${F.periodSel(r)}</div><div class="bx-hm">${c.blk ? `<span class="bx-num bx-big" role="img" aria-label="${L('Block in progress')}">—</span>` : K.num($(st.count ? st.net : 0), 'bx-big' + (neg ? ' bx-rd' : ''), 'today.net')}${sp}</div>${ch}${card}${c.notes.join('')}</div>`;
};
